#!/usr/bin/env python3
"""Build a focused diagnosis review and proposed next contrasts; never launch runs."""
from pathlib import Path
import json,html
import numpy as np
import pandas as pd
import diagnose_shared_receiver_bottlenecks_v1 as d
P=d.P;R=d.R;ROOT=d.ROOT;TAG=d.TAG

def read(name):return d.csv(P/(name+'.csv'))
def screening():
 z=d.npz(d.C/'candidate_index.npz');n=len(z['source_grid']);grid=z['source_grid'];target=z['target_storage'];si=z['link_source'];ri=z['link_receiver'];dist=z['link_distance'].reshape(7,n);ok=z['source_eligible'];z.close()
 links=d.parq(d.C/'intake_receiver_links_preprocessed.parquet');codes=links['Receiver Group'].to_numpy().reshape(7,n)[:,0]
 src=d.parq(d.C/'source_candidates_preprocessed.parquet');core=src['Ward Code'].to_numpy()>0
 named=(codes!=51)[:,None];near=named&(dist<=1000);allpass=np.ones((7,n),bool);states={}
 for case in ['E20240731__H__U','E20240731__L__U']:
  with d.npz(d.C/(case+'_saved_states.npz')) as z:
   ex=np.maximum(z['source_volume']-target,0.);ex[:,~core]=0.;positive=ex>1e-6
   lift=np.maximum(z['receiver_stage'][:,ri]-z['source_stage'][:,si],0).reshape(109,7,n)
   passing=(lift+float(z['receiver_alignment_bound'])<=5.)&((z['source_stage']-z['source_minimum'])>=.05)[:,None,:]
   allpass&=(~positive[:,None,:]|passing).all(axis=0);states[case]=ex
 hasnear=near.any(axis=0);robust=(near&allpass).any(axis=0)&ok
 rows=[];summ=read('july_reference_request_summary');tr=read('july_reference_request_trajectories')
 for case,ex in states.items():
  total=ex.sum(axis=1)/1800;frame=int(np.argmax(total));q=ex[frame]/1800
  cats={'ground_evidence_screen_failed':~ok,'no_named_receiver_within_1000m':ok&~hasnear,'all_positive_frame_trigger_or_head_screen_failed':ok&hasnear&~robust,'robust_link_available':robust}
  assert sum(float(q[m].sum()) for m in cats.values())==float(q.sum()) or np.isclose(sum(q[m].sum() for m in cats.values()),q.sum(),atol=1e-10)
  old=tr[(tr.Case==case)&tr.Frame.eq(frame)].iloc[0]
  assert abs(float(q[~robust].sum())-old['No Robust Named Link Request'])<1e-8
  for key,m in cats.items():rows.append({'case':case,'frame':frame,'screen':key,'positive_candidate_cells':int(((q>1e-9)&m).sum()),'reference_rate_m3_s':float(q[m].sum()),'reference_rate_percent':100*float(q[m].sum())/float(q.sum())})
 out=pd.DataFrame(rows);d.save('july_peak_request_screening',out);return out

def main():
 assert json.loads((R/'validation.json').read_text())['passed']
 screen=screening();road=read('road_effects_whole_window');pop=read('population_effects_whole_window');budget=read('whole_window_operating_budget');pools=read('pump_pool_operating_budget');cov=read('road_priority_spatial_coverage');gr=read('road_group_continuity_proxy');anchor=read('anchor_access_summary');off=read('off_target_summary');ward=read('ward_static_reservations');priority=read('road_priority_effects')
 primary=road[road['Depth Branch'].eq('lower')&road.Scope.eq('Three wards')].copy();pp=pop[pop.bound.eq('lower')&pop.buffer_m.eq(10)&pop.scope.eq('Three wards')]
 table=primary.merge(pp[['event','stage','net_avoided_loss_lower_resident_hours','net_avoided_loss_upper_resident_hours']],left_on=['event','Stage'],right_on=['event','stage'],validate='one_to_one').merge(budget[['event','stage','actual_m3','utilization_percent']],on=['event','stage'],validate='one_to_one')
 table['事件']=table.event.str.replace('E','',regex=False);table['水位']=table.stage
 table['封路暴露减少(km·h)']=table['Closure Reduction km h'];table['减少比例(%)']=table['Closure Reduction Percent']
 table['通达性改善(居民·小时)']=table.apply(lambda x:f"[{x.net_avoided_loss_lower_resident_hours:,.1f}, {x.net_avoided_loss_upper_resident_hours:,.1f}]",axis=1)
 table['实际抽排(m³)']=table.actual_m3;table['预留额度利用率(%)']=table.utilization_percent
 view=table[['事件','水位','封路暴露减少(km·h)','减少比例(%)','通达性改善(居民·小时)','实际抽排(m³)','预留额度利用率(%)']]
 d.save('primary_regional_summary',view)
 # A compact, explicitly proposed matrix. Neither a deployment freeze nor a run authorization.
 common={'rainfall':'unchanged original radar forcing and roof assignment','grid':'same full-domain 10m geometry and subgrid data','horizon_seconds':32400,'forcing_masks':'unchanged original quality masks and scenario stages','selection_data':'July31 H/L requirements only; all three events already inspected, so later transfer checks are development checks, not an untouched test','machine_count':'not prescribed; native intake count is not physical pump count','real_receiving_capacity':'unknown; all shared envelopes are assumptions','run_enabled':False}
 contrasts=[
 {'id':'O1','order':1,'factor':'within-pool reservation allocation rule','layout':'same 62 native intakes and same outlets','budget':'same 0.5m3/s each of five pools; total2.5','change':'fixed reservations -> work-conserving weighted within-pool allocation','rule':'At each actual step, eligible iff depth>=0.05m and lift<=5m. Limit per-site instantaneous rate to min(0.5m3/s, prior available storage/[dt*(1+64*float32 epsilon)]). Allocate the pool minimum of0.5m3/s and sum eligible rates by weighted capped water filling, weights=original site reservations, ties=pump ID. No inter-pool transfer. Reserve only prior storage; no simultaneous rain/face-inflow credit.','fixed':'same trigger, lift limit, positions, receiving stage and pool envelope; original reservation rates retained as weights','implementation':'new allocator and diagnostic rule require isolated operator/clock/source-sink tests before any hydraulic run','question':'Does static idle reservation restrict effective extraction and transport benefit?','first_batch':'July31 H and L; two runs'},
 {'id':'S1','order':2,'factor':'spatial priority for static reservations','layout':'reselect from the same qualified candidate/outlet inventory; derive number of sites','budget':'same0.5m3/s each pool; total<=2.5','change':'local maximum storage priority -> transport-dependency-first priority','rule':'On July H/L frozen requirements only, rank sources lexicographically by max nonincident endpoint dependency among linked road groups, then linked backbone indicator, then local maximum excess/1800s, then grid ID. Retain every original ground/named-receiver/all-positive-frame trigger+head/1000m screen. Reserve min(local request,0.5m3/s,remaining pool envelope); nearest admissible outlet with remaining allowance; same deterministic outlet order. No post hoc retuning to observed benefit.','fixed':'same static reservation operator, target0.30m, horizon1800s, trigger0.05m, lift5m, candidate reach1000m and five pool envelopes','implementation':'offline allocation and serialized source/outlet identity must pass preflight; report if the same budget cannot be fully assigned','question':'Can the same budget protect more transport-critical connections?','first_batch':'July31 H and L; two runs'},
 {'id':'C1','order':3,'factor':'joint source-rate and receiving-envelope scale; conditional second batch','layout':'same62 native intakes, outlets and relative shares','budget':'multiply every original static rate and each pool allowance by2: total5m3/s,1m3/s per pool','change':'joint hypothetical capability envelope, not a pure receiver-capacity effect','rule':'Keep geometry, trigger and lift unchanged. Each doubled site rate remains<=0.5m3/s (verify before running). If this fails, stop and redesign; do not silently clip.','fixed':'same positions and relative rate shares; original static operator','implementation':'existing operator can express this; scenario multiplier2 is an experimental assumption, not an inferred requirement or official capacity','question':'After utilization and placement checks, is a larger combined resource envelope worth testing?','first_batch':'not in the first four runs; optional July H/L only after reviewing O1/S1'}]
 plan={'status':'proposal_only_no_new_hydraulic_execution','common':common,'contrasts':contrasts,
 'reuse':['six qualified no-action/treatment pairs already available','blocked receiving envelope reproduces no-action; reuse it instead of launching a zero-pump run','existing H/L pairs provide stage contrasts; no new arbitrary river-stage series'],
 'not_identified':['Increasing receiver allowance alone while leaving all fixed site rates unchanged produces the identical operator.','Changing to the previous584-site2m3/s-per-pool allocation changes placement and resources together; it cannot identify a pure capacity effect.','A fixed-stage receiver does not calculate downstream acceptance or transferred flood storage.'],
 'first_batch_budget':{'new_cases':4,'sequence':['O1 July H','O1 July L','S1 July H','S1 July L'],'existing_solver_runtime_minutes_range':[float(read('observed_solver_runtimes').runtime_seconds.min()/60),float(read('observed_solver_runtimes').runtime_seconds.max()/60)],'planning_wall_hours':[5,7],'case_soft_budget_hours':2,'resources':'serial; do not assume faster hardware; use existing6CPU/7GiB settings subject to allocator preflight','budget_status':'forecast from existing runs, not a completion guarantee; no process launched'},
 'expansion':'After first four results are reviewed, optionally repeat O1/S1 under September and August H/L (eight further runs); C1 is a separate conditional two-run probe, not automatic. No uninspected event/test claim.',
 'gates':['Preserve all28 original numerical gates and tolerances. Retain8 pump-accounting invariants; O1 must replace only the fixed-rate expectation with an independently reconstructed bound weighted-allocation expectation.','Stop batch dispatch on any identity, mass balance, positivity, clock, source-sink or trace failure. Keep failed outputs quarantined.','Flag any new road closure or negative paired population-access effect for review before expanding. Physical adverse effects remain reportable and are not numerical failures.','If wall time exceeds2h for a case, stop launching further cases after handling the active process safely; do not erase or silently restart it.','Complete all four predeclared cases that pass gates; do not select only favorable events or arms.'],
 'comparison_metrics':['paired closure-length integral km*h, same-time restored/newly closed roads, and censored final-frame closures','priority-group known-member continuity, plus actual whole-domain portal/alternative-path reachability at common times; structural priority is not itself a flood cut','paired resident-hour bounds at0/10/25m, with unknown baseline access held separate; no daytime population or unique-stranded-person claim','actual extraction and time-weighted trigger/head/storage ledgers by pool and ward; closure benefit per actual1000m3 as descriptive, not causal efficiency','outside-candidate-control-area head rise>=0.10m, newly closed roads and adverse population access; downstream receiver storage remains unmodeled'],
 'receiving_screen_followup':'Before enlarging service coverage, review demand-weighted distance/path and receiving eligibility for sources outside the1000m scenario. Do not automatically assume longer transfer routes are feasible; no new hydraulic run is included in this offline check.',
 'decision':'Compare O1 and S1 separately against the original static portfolio; postpone their combination to preserve attribution. A null result is admissible. No empirical benchmark accuracy claim.'}
 d.dump(R/'next_round_plan.json',plan)
 d.save('next_round_contrasts',pd.DataFrame([{k:v for k,v in x.items() if k not in ['rule','fixed','implementation']} for x in contrasts]))
 evidence=[
 {'candidate_bottleneck':'overall extraction scale','finding':'closure exposure reduction1.14-2.39%; July peak proxy request42.25m3/s vs static total2.5; no engineering required-capacity estimate','status':'resource scale may matter; not causally separated from placement/receiving screens','next_contrast':'conditional C1 after O1/S1'},
 {'candidate_bottleneck':'static reservation utilization','finding':'full-window utilization23.54-67.79%; unspent volume dominated by trigger, with per-pool divergence; fixed-state reallocatable envelope is not a predicted outcome','status':'direct operating evidence; causal transport benefit still untested','next_contrast':'O1'},
 {'candidate_bottleneck':'transport-critical spatial coverage','finding':'23 of577 nonincident-dependency candidate groups directly share selected intake cells; wider indirect benefit is observed','status':'priority coverage is limited under this geometric co-location measure, not a hydraulic influence map','next_contrast':'S1'},
 {'candidate_bottleneck':'head cutoff on selected sources','finding':'head-only blockage<0.6% of full-window nominal volume in all six cases; combined trigger/head classified separately','status':'not the main logged selected-site restriction under current5m assumption; excludes unselected sources and real downstream acceptance','next_contrast':'reuse H/L; no receiver-only capacity rerun'},
 {'candidate_bottleneck':'downstream acceptance / transferred risk','finding':'fixed-stage external sinks omit added receiver storage;0-500m2 outside-candidate-control-area simultaneous head-rise screen is small but incomplete','status':'physical acceptance remains unknown','next_contrast':'bound scenarios only; do not call absence of new road closure proof of no transfer risk'}]
 d.save('bottleneck_evidence',pd.DataFrame(evidence))
 # Build a compact whole-ward readable review with expandable machine-readable data.
 cause=budget[['event','stage','requested_m3','actual_m3','trigger_only_m3','head_only_m3','both_blocked_m3','eligible_storage_shortfall_m3']].copy()
 for c in cause.columns[3:]:cause[c]=100*cause[c]/cause.requested_m3
 cause=cause.drop(columns='requested_m3').rename(columns={'event':'事件','stage':'水位','actual_m3':'实际抽排(%)','trigger_only_m3':'仅未达启动水深(%)','head_only_m3':'仅扬程超限(%)','both_blocked_m3':'两条件同时受阻(%)','eligible_storage_shortfall_m3':'合格时储量限流(%)'})
 poolview=pools.pivot_table(index='Receiving Pool',columns=['event','stage'],values='utilization_percent').round(1);poolview.columns=[' / '.join(c) for c in poolview.columns];poolview=poolview.reset_index()
 gs=[]
 for (e,s),df in gr[gr.branch.eq('lower')].groupby(['event','stage']):
  affected=df[df.restored_edge_km_h.gt(1e-8)];full=affected[affected.all_registered_members_qualified]
  gs.append({'事件':e,'水位':s,'组内有路段恢复的道路组':len(affected),'其中全部成员均有合格数据':len(full),'这些组内整体关闭时长缩短':int(full.known_group_closure_reduction_hours.gt(1e-8).sum())})
 anchorv=anchor[anchor.bound.eq('lower')&anchor.arm.eq('drainage')][['event','stage','frame','restored_endpoints','newly_lost_endpoints','median_same_endpoint_cost_ratio','ratio_p95']]
 pr=priority[priority.branch.eq('lower')].copy();pr['benefit_share_percent']=100*pr.net_reduction_km_h/pr.groupby(['event','stage']).net_reduction_km_h.transform('sum')
 d.save('priority_benefit_shares',pr)
 wardrd=road[road['Depth Branch'].eq('lower')&road.Scope.ne('Three wards')][['event','Stage','Scope','Closure Reduction km h','Closure Reduction Percent']]
 ptext=''.join(f'<article><h3>{x["id"]} · {html.escape(x["factor"])}</h3><p><b>问题：</b>{html.escape(x["question"])}</p><p>{html.escape(x["change"])}。{html.escape(x["budget"])}。</p><p><b>固定：</b>{html.escape(x["fixed"])}</p><p><b>准入准备：</b>{html.escape(x["implementation"])}</p></article>' for x in contrasts)
 notes='''<p>收益小不能直接归因于某一个因素。目前能确认：局部储水优先的静态部署只直接关联少量交通依赖候选道路组；静态预留在部分取水点未启动时闲置；不同接收池的负荷差异很大。究竟改布局还是改调配更有用，需要分离对照。</p><p>0.5m³/s单点上限、每池0.5m³/s、5m扬程和1000m直线连接均为情景假设。62是10m原生取水单元数量，不能等同设备台数。所有五个池的静态预留之和都达到0.5m³/s，最大的单点预留仅0.17061m³/s，单点上限并未限制原静态分配。</p>'''
 links=''.join(f'<li><a href="../../../processed/{TAG}/{f.name}">{html.escape(f.name)}</a></li>' for f in sorted(P.glob('*.csv')))
 page=f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>三区排水部署瓶颈诊断</title><style>body{{font:16px/1.75 system-ui,sans-serif;color:#203d4b;background:#f6f8fa;margin:0}}main{{max-width:1350px;margin:auto;padding:30px 24px}}h1{{line-height:1.3}}h2{{margin-top:2em;border-bottom:1px solid #ccd9df;padding-bottom:.4em}}aside,article,.note{{background:white;padding:18px 22px;border-radius:8px;margin:16px 0}}aside{{border-left:5px solid #277b80}}.note{{border-left:5px solid #c08b31}}table{{border-collapse:collapse;font-size:13px;background:white;width:100%}}th,td{{border:1px solid #d2dde2;padding:9px;text-align:left}}th{{background:#e9f0f3}}.scroll{{overflow-x:auto;margin:16px 0}}summary{{cursor:pointer}}a{{color:#16687f}}small{{color:#506774}}</style><main><h1>三区排水部署：收益为什么有限？</h1><aside>已完成六组、三场暴雨的既有结果诊断；<b>本轮新模拟0次</b>。统一道路支撑为836.958km，全部原准入检查通过。全过程封路暴露减少<b>1.14%–2.39%</b>。建议优先检验“同预算调配”和“同预算改布局”，再决定是否扩大资源包。</aside>{notes}<h2>1. 全过程收益：道路与居民通达性</h2>{d.tab(view)}<p>主表采用水深下界分支、人口接入10m规则；H/L为既有河道水位情景。完整上下界、0/10/25m及分区结果见数据。封路暴露是封路长度对时间的积分，非独立道路总长度；居民·小时保留逐块配对上下界，非置信区间或独立受困人数。不能把两端分别相减重建改善区间。夜间基线为2020常住人口，未加入白天实际在场人数。</p><p>例如9月事件代表时刻人口改善为0，整场仍有[9,12001]居民·小时的改善区间（H）。单时刻不能替代全过程。六组均没有新增封路；原粗尺度代表节点在冻结代表时刻无新增可达端点，同端点路径成本比中位数和95%分位仍为1，<b>不能由此宣称减少了真实交通拥堵</b>。</p><details><summary>三区分区道路收益与代表节点核对</summary>{d.tab(wardrd)}{d.tab(anchorv)}</details><h2>2. 能力没有全部用满：原因是什么？</h2>{d.tab(cause)}<p>上表为同一步日志按实际步长累计的体积占比，各行合计100%。完整9h名义预留体积约81000m³；干燥前段也计入分母，所以利用率低不能直接推断能力过剩。储量限流为0，说明合格运行时所请求流量未受可用储量截断；未达启动水深仍可能反映水体未到取水位置，不能据此推断周边没有排水需求。</p><p>仅扬程超限的份额均不足0.6%；“启动水深与扬程同时受阻”另列，不强行归因。此结论仅适用于已选位置及当前5m假设，未选位置的接收连接筛查、排水路径和真实下游承受能力仍可能受限。</p><h3>接收池的预留利用率（%）</h3>{d.tab(poolview)}<p>古川在8月和9月达到约94%，亀島川与日本橋川则明显较低。这支持分别研究各池的调配和位置覆盖。日志还计算了在既有状态上允许池内重新调配的逐步能力包络；该积分只是诊断量，不是额外可抽排量预测，更不能换算成确定道路收益。</p><h2>3. 是否覆盖了重要的通行链路？</h2>{d.tab(cov)}<p>577个“非相邻端点依赖”候选组中，只有23个组直接与已选取水单元共址（约4.0%）；39/2152个全部候选道路组与这些单元直接关联。这里的依赖来自正常网络的道路组关闭试探，并非暴雨时真实割集；共址也不是排水影响范围。实际结果中121–214个道路组曾有路段恢复，说明间接影响超出共址组，不能把未共址当作完全未受保护。</p>{d.tab(pd.DataFrame(gs))}<p>有路段恢复并不保证整条通行链路恢复。上表仅统计已登记道路组、已知成员是否仍有关闭路段；它不是连通分量或完整替代路径检验。下一轮应同时比较全域替代路径及居民接入，保留桥隧未知分支。</p><details><summary>各区静态额度与道路优先类别收益</summary>{d.tab(ward)}{d.tab(pr[['event','stage','priority_evidence','baseline_km_h','net_reduction_km_h','benefit_share_percent']])}</details><h2>4. 参考需求与接收条件：目前能量化到哪里？</h2><p>7月H在全域参考需求峰值时刻，30分钟局部快照代理为42.252m³/s，当前同帧分配2.401m³/s；其中26.964m³/s在原保守筛查下没有合格具名连接，另12.887m³/s为静态分配缺口。它们不是工程设计流量，也不是实际无法排走的水量。代理没有计算措施后的来水和排水反馈，重复时刻不能累计成总需求。该分解仅来自7月，不能替代另两场的区域来水预算。</p>{d.tab(screen)}<p>7月H峰值参考需求中，55.6%仅因1000m内没有具名模型连接而未通过，另有7.35%未通过地面证据筛查、0.84%未通过全正需求时段启动／扬程筛查。这表明空间连接假设是重要的离线覆盖限制，不能靠给原62点加流量自动覆盖三区。筛查依次分为地面证据不足、1000m内没有具名连接、所有正需求时刻的启动／扬程条件不全通过，以及有稳健连接。因而“无合格连接”不等于现场没有出水口或河流。仍缺真实接收许可、路径、下游容量和受纳水体增量水位响应。</p><h2>5. 是否把积水转移到其他片区？</h2><p>六组在共同已知道路上均无新增封路；候选道路控制区之外，同时水头抬升≥0.10m的最大面积为0–500m²。这里“之外”排除13,214个候选道路控制单元，并非仅排除62个实际取水单元；候选区内部的转移不包含在这项面积统计中。受纳点设固定水位并将抽排量显式移出模型，没有计算该水量进入河道后的新增储水，<b>不能据此排除下游风险转移</b>。</p><details><summary>原分区水头变化记录</summary>{d.tab(off)}</details><h2>6. 下一轮：先用小对照拆开机制</h2><aside>建议首批仅O1与S1，各跑原7月H/L，共4次；原基线直接复用。现有单次约58–74分钟，首批按串行及核验预留<b>5–7小时</b>。O1须先实现和验证新调配算子。<b>本轮只提出方案，没有构建新运行目录或启动计算。</b></aside>{ptext}<p>O1和S1分别与原组合比较，先不叠加；C1的两倍能力是明确的情景假设，属于取水能力与接收额度共同扩大，不能解释成单独接收能力效应。只扩大接收额度、保持原固定流量文件不变，将得到相同抽排算子，因此不安排这种无效模拟。旧584位置方案同时改变布局与规模，也不作为纯能力对照。</p><p>四组全部通过原28项数值门槛和相应8项抽排核验后再看效果；身份、时钟、水量平衡、正性或调配重建失败即停止后续派发。新增封路或人口通达性恶化须保留并复核，不算作需要隐去的失败。下一阶段可把O1/S1移植至另两场H/L；三场均已参与诊断，不能再称为封存的独立测试。详见下方完整规则、预算和停止条件。</p><h2>文件与复现</h2><p><a href="next_round_plan.json">下一轮完整方案</a> · <a href="validation.json">分析核验</a> · <a href="protocol.json">口径与限制</a> · <a href="README.md">复现步骤</a></p><details><summary>导出表格</summary><ul>{links}</ul></details><p><small>Human decision MILI-D-20261020-023。本轮不修改AnaSOP，不调参、不搜索benchmark、不训练，不触碰封存测试。</small></p></main></html>'''
 (R/'review.html').write_text(page)
 protocol={'units':{'road_integral':'km*h on common qualified support; length not vehicle-flow loss','population_integral':'resident*h paired stock-access bounds; not unique people or a confidence interval','trace_lost_volume':'nominal reservation volume withheld by mutually exclusive trigger/head flags and eligible storage clipping','group_continuity':'any known member closed; not actual network cut','conditional_envelope':'integral of instantaneous water-filling feasibility on fixed observed treatment states; not an achievable cumulative counterfactual','off_target_area':'km2; outside13214candidate road-control cells (not merely62intakes); fixed receiver storage not represented'},'primary_view':'lower depth;10m population candidate buffer; complete exports retain all prior alternatives','no_new_runs':True,'preserved':'original rain,stage,mesh,roof allocation,masks,identity and all numerical thresholds','demand':'July30min snapshot clearance proxy only; no temporal volume summation; no required capacity claim','scope':'three wards; proposed road policy alternatives remain unfrozen; no engineering feasibility or benchmark accuracy claim','decision_record':'MILI-D-20261020-023','report_script_sha256':d.sha(Path(__file__))}
 d.dump(R/'protocol.json',protocol)
 (R/'README.md').write_text('''# Shared receiver bottleneck diagnosis\n\nFrom the project root:\n\n```sh\n.venv/bin/python src/analyses/diagnose_shared_receiver_bottlenecks_v1.py\n.venv/bin/python src/analyses/build_shared_receiver_diagnosis_review_v1.py\n```\n\nThe first script reads six completed treatments and their original paired exposure/access tables. It streams and hashes all six per-step pump traces, verifies unchanged original audits and per-step operating categories, independently re-integrates the existing road and paired resident-hour summaries, checks identical road/admission support and partitions road benefits by disjoint priority groups. It never calls a solver. The second script decomposes the existing July snapshot screen, writes an explicitly proposed small contrast plan, and builds the offline review. Browser QA: run `node src/visualization/validate_shared_receiver_diagnosis_v1.cjs` with the local Playwright/Chrome runtime. Neither script modifies original results, AnaSOP, rainfall, masks, source data or test custody.\n\nOriginal CSVs retain prior units: road trajectory lengths are km, times are seconds, closure integrals are km*h. Resident-hour bounds are paired per-block stock-access intervals, not confidence limits, unique people or daytime occupancy. Road group-union dependency probes are structural priorities, not observed simultaneous cuts. Direct intake/grid co-location is not hydraulic coverage. All nominal allowances, unit limits, reach, lift and service horizon are hypothetical. Fixed receivers omit downstream added storage.\n\n`input_bindings.json` records SHA256 of all main-analysis inputs including large traces, hashed during their single parse. `supplementary_input_bindings.json` binds report inputs and the prior analysis manifest. `validation.json` records original audit status plus independent analysis checks. `next_round_plan.json` is proposed only, execution disabled.\n''')
 d.dump(P/'supplementary_input_bindings.json',{'sha256':d.BIND,'main_bindings_sha256':d.sha(P/'input_bindings.json'),'report_script_sha256':d.sha(Path(__file__))})
 # Numerical assertions on claims used verbatim by the review.
 assert primary['Closure Reduction Percent'].between(1.14,2.40).all()
 assert primary['Maximum Same Time Newly Closed km'].abs().max()<1e-9
 assert budget.eligible_storage_shortfall_m3.abs().max()<1e-6
 assert (100*budget.head_only_m3/budget.requested_m3<.6).all()
 assert cov.groups_linked_to_selected_cell.sum()==39
 crit=cov[cov['Priority Evidence'].isin(['backbone_and_nonincident_dependency','nonincident_access_dependency'])];assert crit.groups.sum()==577 and crit.groups_linked_to_selected_cell.sum()==23
 assert anchorv.restored_endpoints.eq(0).all() and anchorv.newly_lost_endpoints.eq(0).all()
 assert np.allclose(anchorv.median_same_endpoint_cost_ratio,1) and np.allclose(anchorv.ratio_p95,1)
 d.dump(R/'report_validation.json',{'passed':True,'hardcoded_claims_checked_against_exports':True,'primary_groups':len(primary),'input_files_bound':len(d.BIND),'all_next_contrasts_execution_disabled':True,'new_hydraulic_runs':0})
 print('REVIEW_READY',R/'review.html',flush=True)
if __name__=='__main__':main()
